mapper.insert:
INSERT INTO PT_USER_ROLE (
    USER_ID, ROLE_ID, DEFAULT_ASSIGN, INHERIT_ASSIGN, GROUP_ASSING, CREATE_TIME
) VALUES (
    #{userId}, #{roleId}, #{defaultAssign}, #{inheritAssign}, #{groupAssing}, #{createTime}
)

mapper.delete:
DELETE FROM PT_USER_ROLE
WHERE USER_ID = #{userId}
  AND ROLE_ID = #{roleId}

mapper.select:
SELECT COUNT(*)
FROM PT_USER_ROLE
WHERE ROLE_ID = #{roleId}

SELECT u.USER_ID, u.USERNAME, u.USERCHNNAME, u.EMAIL, u.ISEXPIRED, u.ISLOCKED, u.PASS_WRONG_COUNT, u.ISENABLED, u.CREATE_TIME, u.CREATE_AUTHOR, u.UPDATE_TIME, u.UPDATE_AUTHOR, u.REMARK, u.PWD_UPDATE_TIME FROM PT_USER u INNER JOIN PT_USER_ROLE ur ON u.USER_ID = ur.USER_ID WHERE ur.ROLE_ID = #{roleId}
AND (u.USERNAME LIKE CONCAT('%', #{keyword}, '%') OR u.USERCHNNAME LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

SELECT u.USER_ID AS empId, u.USERNAME AS username, u.USERCHNNAME AS displayName, uo.ORG_CODE AS orgCode, o.ORG_NAME AS orgName, ur.CREATE_TIME AS bindTime FROM PT_USER u INNER JOIN PT_USER_ROLE ur ON u.USER_ID = ur.USER_ID AND ur.ROLE_ID = #{roleId} LEFT JOIN EXT_USER_ORG uo ON u.USER_ID = uo.USER_ID LEFT JOIN EXT_ORG_INFO o ON uo.ORG_CODE = o.ORG_CODE WHERE 1=1
AND (u.USERNAME LIKE CONCAT('%', #{keyword}, '%') OR u.USERCHNNAME LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ur.CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

SELECT ur.USER_ID AS userId, r.ROLE_ID AS roleId, r.ROLE_CODE AS roleCode, r.ROLE_CHNAME AS roleChName FROM PT_ROLE r INNER JOIN PT_USER_ROLE ur ON r.ROLE_ID = ur.ROLE_ID WHERE ur.USER_ID IN
#{uid}
AND r.RECORD_STATUS = 0
